<?php require_once 'config.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$s=$conn->prepare('SELECT * FROM users WHERE email=?');$s->bind_param('s',$email);$s->execute();$u=$s->get_result()->fetch_assoc();if($u&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['name']=$u['name'];$_SESSION['role']=$u['role'];header('Location: dashboard.php');exit;}$error='Invalid email or password.';}$page_title='Login';include 'header.php';?>
<div class="form"><h1>Welcome back</h1><?php if(isset($_GET['registered'])) echo '<p class="success">Registration successful. Please log in.</p>'; ?><?php if($error): ?><p class="error"><?= htmlspecialchars($error) ?></p><?php endif; ?><form method="post"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button>Login</button></form><p>New user? <a href="register.php">Register</a></p></div><?php include 'footer.php'; ?>